/**
 * Increment the solver frame counter.
 * Called once per physics step.
 */
export function incrementSolverFrame(): void;
/**
 * Get or create a manifold for a body pair.
 *
 * @param {number} indexA - First body index
 * @param {number} indexB - Second body index
 * @returns {ContactManifold}
 */
export function getOrCreateManifold(indexA: number, indexB: number): ContactManifold;
/**
 * Get a manifold for a body pair if it exists.
 *
 * @param {number} indexA - First body index
 * @param {number} indexB - Second body index
 * @returns {ContactManifold|null}
 */
export function getManifold(indexA: number, indexB: number): ContactManifold | null;
/**
 * Prune old manifolds and their contacts.
 * Called after each physics step.
 *
 * @param {number} maxAge - Maximum frames since last use
 */
export function pruneManifolds(maxAge?: number): void;
/**
 * Clear all manifolds (for level transitions, etc).
 */
export function clearAllManifolds(): void;
/**
 * Reset manifold "solved" flags for new solver pass.
 */
export function resetManifoldSolvedFlags(): void;
/**
 * Get manifold count (for debugging).
 * @returns {number}
 */
export function getManifoldCount(): number;
/**
 * Get total contact point count (for debugging).
 * @returns {number}
 */
export function getTotalContactCount(): number;
/**
 * Single contact point within a manifold.
 * Stores geometry and cached impulses for warm starting.
 */
export class ContactPoint {
    localPointA: any;
    localPointB: any;
    worldPoint: any;
    normal: any;
    penetration: number;
    normalImpulse: number;
    tangentImpulse1: number;
    tangentImpulse2: number;
    lastFrameUsed: number;
    /**
     * Reset contact point for reuse from pool.
     */
    reset(): void;
    /**
     * Copy data from another contact point.
     * @param {ContactPoint} other - Source contact
     */
    copy(other: ContactPoint): void;
}
/**
 * Contact manifold between two bodies.
 * Maintains persistent contacts for warm starting.
 */
export class ContactManifold {
    /**
     * @param {number} bodyIndexA - First body index (always lower)
     * @param {number} bodyIndexB - Second body index
     */
    constructor(bodyIndexA: number, bodyIndexB: number);
    bodyA: number;
    bodyB: number;
    points: any[];
    friction: number;
    restitution: number;
    lastFrameUsed: number;
    solved: boolean;
    /**
     * Add or update a contact point in the manifold.
     *
     * @param {THREE.Vector3} worldPoint - Contact point in world space
     * @param {THREE.Vector3} normal - Contact normal (A → B)
     * @param {number} penetration - Penetration depth
     * @param {THREE.Object3D} transformerA - Body A transformer
     * @param {THREE.Object3D} transformerB - Body B transformer
     * @param {number} currentFrame - Current physics frame
     */
    addContact(worldPoint: THREE.Vector3, normal: THREE.Vector3, penetration: number, transformerA: THREE.Object3D, transformerB: THREE.Object3D, currentFrame: number): void;
    /**
     * Find an existing contact near the given local point.
     *
     * @param {THREE.Vector3} localPoint - Point to match in body A local space
     * @param {number} threshold - Distance threshold
     * @returns {ContactPoint|null} Matching contact or null
     */
    findMatchingContact(localPoint: THREE.Vector3, threshold: number): ContactPoint | null;
    /**
     * Replace the least useful contact when manifold is full.
     * Strategy: Replace shallowest penetration.
     *
     * @param {ContactPoint} newContact - New contact to add
     */
    replaceLeastUsefulContact(newContact: ContactPoint): void;
    /**
     * Remove stale contacts that haven't been updated recently.
     *
     * @param {number} currentFrame - Current physics frame
     * @param {number} maxAge - Maximum frames since last update
     */
    pruneContacts(currentFrame: number, maxAge?: number): void;
    /**
     * Clear all contacts and return them to pool.
     */
    clear(): void;
    /**
     * Get deepest penetrating contact.
     * @returns {ContactPoint|null}
     */
    getDeepestContact(): ContactPoint | null;
}
/**
 * Global manifold cache.
 * Key format: "minIdx_maxIdx" to ensure consistent lookup.
 */
export const manifoldCache: Map<any, any>;
/**
 * Current solver frame counter.
 * Incremented each physics step for age tracking.
 */
export let solverFrameCounter: number;
